
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_thakkar_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_thakkar", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.361143613580224e+01, 9.001066384785035e+01, 8.508589995834004e+01, 7.849668592918313e+01, 6.995306580202073e+01, 5.935977750522662e+01, 4.703015840914619e+01, 3.389620081939965e+01, 2.151376220243718e+01, 1.160012501838182e+01, 5.189478094669090e+00, 2.524869605858764e+00, 1.890947525406943e+00, 1.268979853669025e+00, 6.506747762673688e-01, 2.527428346848103e-01, 7.496647116955048e-02, 1.622797296143872e-02, 2.294904831882194e-03, 1.791452449735944e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


